const float Max_Iter = 1024.0 * 4.0;
const float ZoomX = 0.6591999;
const float ZoomY = 0.4500298;


float mandelbrot(vec2 uv) {
    vec2 c = 5.0 * uv - vec2(0.7 , 0.0);
    c = c / pow((iTime + 2.5) / 3.0, 4.0) - vec2(ZoomX, ZoomY);
    vec2 z = vec2(0.0);
    float iter = 0.0;
    for (float i; i < Max_Iter; i++) {
        z = vec2(z.x * z.x - z.y * z.y, 2.0 * z.x * z.y) + c;
        if (dot(z, z) > 4.0 ) return iter / Max_Iter;
        iter++;
    }
    return 0.0;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv =(fragCoord - 0.5 * iResolution.xy) /  iResolution.y;
    vec3 col = vec3(0.0);

    float m = mandelbrot(uv);
    col.xy += m;
    col = pow(col, vec3(0.25/1.0));


    fragColor = vec4 (col,1.0);
}
